```python
from collections import OrderedDict


class LRUCache:
    """A fixed-capacity cache that evicts the least recently used entry.

    Both `get` and `put` count as uses, so touching a key moves it to the
    most-recently-used end of the underlying OrderedDict.
    """

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0

    def get(self, key, default=None):
        """Return the value for `key`, marking it as recently used."""
        if key not in self._data:
            self._misses += 1
            return default
        self._hits += 1
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Insert or update `key`, evicting the oldest entry if needed."""
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def stats(self):
        """Return hit/miss counts and current occupancy."""
        return {"hits": self._hits, "misses": self._misses, "size": len(self._data)}

    def __contains__(self, key):
        # Membership tests do not count as a use, and are not scored.
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        items = ", ".join(f"{k!r}: {v!r}" for k, v in self._data.items())
        return f"LRUCache(capacity={self.capacity}, {{{items}}})"


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    cache.get("a")          # hit; "a" is now the most recent
    cache.put("c", 3)       # evicts "b"
    cache.get("b")          # miss
    print(cache)            # LRUCache(capacity=2, {'a': 1, 'c': 3})
    print(cache.stats())    # {'hits': 1, 'misses': 1, 'size': 2}
